{"command":"cd out && unzip -p 五周年庆典策划案.docx word/styles.xml | python3 -c "
import sys,re
s=sys.stdin.read()
for sid in ['Heading1','Heading2','Heading3']:
    m=re.search(r'<w:style w:type=\"paragraph\" w:styleId=\"%s\">.*?</w:style>'%sid,s,re.S)
    if m: print(sid, re.findall(r'<w:rFonts[^/]*/>',m.group(0)), re.findall(r'<w:sz w:val=\"[0-9]+\"/>',m.group(0)), re.findall(r'<w:color[^/]*/>',m.group(0)))
"","description":"Check heading fonts in output styles"}

